const h = $input.first().json.headers || {};
const total = parseInt(h['x-pagination-total-count'], 10);
if (isNaN(total)) { throw new Error('No total count header'); }
const pages = Math.max(1, Math.ceil(total / 500));
const out = [];
for (let p = 1; p <= pages; p++) { out.push({ json: { page: p, total: total, pages: pages } }); }
return out;

const pages = $input.all();
const expected = $('Expand Pages').first().json;
let keysSeen = 0;
const badPages = [];
const hits = [];
const stats = { es_total: 0, es_with_guillemets: 0, es_with_double_angle: 0, es_with_curly: 0, es_with_straight: 0 };
function txt(v) { if (v === null || v === undefined) { return ''; } return (typeof v === 'string') ? v : JSON.stringify(v); }
for (let i = 0; i < pages.length; i++) {
  const b = pages[i].json || {};
  if (!Array.isArray(b.keys)) { badPages.push(i + 1); continue; }
  for (const k of b.keys) {
    if (k.is_archived) { continue; }
    keysSeen++;
    let en = '';
    let es = null;
    for (const tr of (k.translations || [])) {
      if (tr.language_iso === 'en') { en = txt(tr.translation); }
      if (tr.language_iso === 'es') { es = tr; }
    }
    if (!es) { continue; }
    const v = txt(es.translation);
    if (!v) { continue; }
    stats.es_total++;
    const g = /[\u00ab\u00bb]/.test(v);
    const d = /<<|>>/.test(v);
    if (g) { stats.es_with_guillemets++; }
    if (d) { stats.es_with_double_angle++; }
    if (/[\u201c\u201d]/.test(v)) { stats.es_with_curly++; }
    if (/"/.test(v)) { stats.es_with_straight++; }
    if (g || d) {
      const kn = k.key_name || {};
      hits.push({
        key_id: k.key_id,
        key: kn.web || kn.other || kn.ios || kn.android || '',
        translation_id: es.translation_id,
        is_plural: !!k.is_plural,
        form: g && d ? 'both' : (g ? 'guillemets' : 'double_angle'),
        en: en,
        es: v,
        en_has_curly: /[\u201c\u201d]/.test(en),
        en_has_straight: /"/.test(en),
        en_has_angle: /<<|>>|[\u00ab\u00bb]/.test(en),
        modified_by: es.modified_by_email || '',
        modified_at: es.modified_at || '',
        statuses: (es.custom_translation_statuses || []).map(function (s) { return s.title; }).join(',')
      });
    }
  }
}
return [{ json: { expected_total: expected.total, pages_expected: expected.pages, pages_received: pages.length, bad_pages: badPages, keys_seen: keysSeen, stats: stats, hit_count: hits.length, hits: hits } }];
